RUNTIME_SHA = 'f9a8e8b0998cc74a37f6aaa7fae99a21c29e712e9cc32f21507eeba65ef2e077'
PHYSICAL_STEPS = 3_010_560
HOT_STEPS = 1_003_520
SEEDS = (2001,2002,2003,2004)
DELAYS = (0,1,3)

def clean(value):
    if isinstance(value, dict): return {str(k):clean(v) for k,v in value.items()}
    if isinstance(value, (list,tuple)): return [clean(v) for v in value]
    if hasattr(value,'tolist'): return clean(value.tolist())
    if isinstance(value,float) and not math.isfinite(value): return None
    return value

def read(path, default=None):
    p=Path(path)
    if p.is_symlink(): raise RuntimeError('拒绝读取链接状态文件：'+str(p))
    return json.loads(p.read_text(encoding='utf-8-sig')) if p.exists() else default

def save(path, value):
    p=Path(path); p.parent.mkdir(parents=True,exist_ok=True)
    if p.is_symlink(): raise RuntimeError('拒绝覆盖链接')
    tmp=p.with_name(p.name+'.pending_'+str(os.getpid()))
    tmp.write_text(json.dumps(clean(value),ensure_ascii=False,indent=2,allow_nan=False),encoding='utf-8')
    os.replace(tmp,p)

def digest(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as f:
        for block in iter(lambda:f.read(1024**2),b''): h.update(block)
    return h.hexdigest()

def load_module(name, blob, wanted):
    raw=zlib.decompress(base64.b85decode(blob))
    if hashlib.sha256(raw).hexdigest()!=wanted: raise RuntimeError('内嵌源码校验失败')
    tree=ast.parse(raw.decode('utf-8-sig'))
    tree.body=[n for n in tree.body if not (isinstance(n,ast.If) and isinstance(n.test,ast.Compare)
        and isinstance(n.test.left,ast.Name) and n.test.left.id=='__name__')]
    m=types.ModuleType(name);m.__file__=str(Path(__file__).resolve());sys.modules[name]=m
    exec(compile(tree,'<'+name+'>','exec'),m.__dict__)
    import cloudpickle
    cloudpickle.register_pickle_by_value(m)
    return m

def task_record(arm, seed, **extra):
    return dict(id=f'E1_K3_{arm}_s{seed}',environment='E1',k=3,fleet=12,seed=seed,
        arm=arm,control='J3',method='J3__M0_BASE',variant='M0_BASE',reward_mode='PT_POST',
        time_mode='RAW',timing=True,batch=True,network='TRANSFORMER',gamma=.99,**extra)

def runtime(root, task):
    """只使用封存作者环境，不执行另外一个矩阵的入口。"""
    m=load_module('threeway_runtime',RUNTIME_B85,RUNTIME_SHA)
    native=m.materialize_source(Path(root)).resolve()
    for prefix in ('at_obj','utilss','rl_env','policy'):
        for name in tuple(sys.modules):
            if name==prefix or name.startswith(prefix+'.'):
                fn=getattr(sys.modules[name],'__file__',None)
                if fn and not Path(fn).resolve().is_relative_to(native):
                    raise RuntimeError('发现非封存作者模块，拒绝混用：'+name)
    sys.path[:]=[str(native)]+[p for p in sys.path if str(p)!=str(native)]
    os.environ.update(UAM_STRICT_MODE='E1',UAM_STRICT_FLEET='12',UAM_STRICT_LOG_EVENTS='0',
        MPLCONFIGDIR=str(Path(root)/'cache'),XDG_CACHE_HOME=str(Path(root)/'cache'))
    m.gap_setup(task,Path(root),'train')
    from loguru import logger
    logger.remove();m.torch.set_num_threads(1)
    return m,native

def bank_make(root, native):
    """保留原OD多重集和到达时刻；新顺序只叫条件重排，不叫新需求分布。"""
    source=Path(native)/'train_data/passengers_300.csv'
    with source.open(encoding='utf-8-sig',newline='') as f:
        r=csv.DictReader(f);fields=r.fieldnames;rows=list(r)
    if len(rows)!=300: raise RuntimeError('源需求不符')
    spatial=[k for k in fields if k.lower() not in ('id','person_id','time','timestamp','arrival','arrival_time','request_time')]
    records=[]
    for seed in (4301,4302,4303,4304,7401,7402,7403,7404):
        od=[{k:x[k] for k in spatial} for x in rows];random.Random(seed).shuffle(od)
        stream=io.StringIO(newline='');w=csv.DictWriter(stream,fieldnames=fields);w.writeheader()
        w.writerows([dict(x,**o) for x,o in zip(rows,od)])
        p=Path(root)/'bank'/f'order_{seed}.csv';blob=stream.getvalue().encode('utf-8')
        p.parent.mkdir(parents=True,exist_ok=True)
        if p.exists() and p.read_bytes()!=blob: raise RuntimeError('需求顺序改变')
        if not p.exists():p.write_bytes(blob)
        records.append(dict(name=p.stem,path=str(p),sha256=digest(p),
            role='开发验证' if seed<7000 else '方法固定后的条件顺序确认；非新分布'))
    save(Path(root)/'BANK.json',records)
    return str(source),records

def fresh_env(m, root, task, trace, horizon, seed):
    env=m.FullEnv(Path(root),3,horizon,str(trace),'J3__M0_BASE','E1',rank=0)
    obs,_=env.reset(seed=int(seed))
    return env,obs

def lq_target(env):
    s=env.scenario;candidates=tuple(str(v) for v in env._three_m.CANDIDATES[env.k])
    def key(v):
        q=len(s.vertiports.vertiport_list[v].person_list)
        ready=sum(e.state.name=='IDLE' and not e.passenger_ids for e in s.vertiports.evtols_at_vertiport[v])
        return q,-ready,-int(v)
    return candidates.index(max(candidates,key=key))

class DispatchGate:
    """只改变V2空返批次的释放时刻；其他时钟、能耗和满座规则完全照常。"""
    def __init__(self, env, m):
        self.env=env;env._three_m=m;self.remaining=0;self.target=0;self.release=False
        self.request=None;self.events=[];self.original=env._dispatch_hook
        env.scenario._strict_dispatch_returns=types.MethodType(self.hook,env.scenario)
    def hook(self, scenario_unused, *unused):
        env=self.env
        if self.remaining>0:
            self.remaining-=1
            self.events.append(dict(time=env.scenario.time,kind='等待',remaining=self.remaining,target=self.target))
            return None
        if self.release:
            env._priority=self.target;self.release=False
            self.events.append(dict(time=env.scenario.time,kind='释放',target=self.target))
        elif self.request is not None:
            target,delay=self.request;self.request=None
            if delay:
                self.target=target;self.remaining=delay-1;self.release=True
                self.events.append(dict(time=env.scenario.time,kind='开始等待',delay=delay,target=target))
                return None
            env._priority=target
        previous={str(e.id):e.state.name for e in env.scenario._all_evtols.values()}
        result=self.original(env.scenario)
        executed=[dict(aircraft=str(e.id),target=str(getattr(e,'target_vertiport_id','')))
            for e in env.scenario._all_evtols.values() if e.state.name=='FLYING' and previous[str(e.id)]!='FLYING']
        if executed:self.events.append(dict(time=env.scenario.time,kind='实际空返',priority=int(env._priority),executed=executed))
        return result
    def metadata(self):
        values=[float(self.remaining+int(self.release))/3.]+[float(self.release and self.target==i) for i in range(3)]
        return values

def metric_start():
    return dict(area=0.,individual=Counter(),phases=Counter(),board={},decision_log=[],
                projection_count=0,decision_count=0,effectless_air=0)

def metric_tick(env, ledger):
    s=env.scenario;finished=set(s.finished_ids)
    for pid,p in s.persons.persons.items():
        if pid in finished:continue
        key=str(pid);ledger['individual'][key]+=1;ledger['area']+=1
        sub=str(getattr(p,'sub_state','unknown'))
        phase='ground' if sub in ('ground','car','access','drive','to_vertiport') else 'flight' if sub=='fly' else 'wait'
        ledger['phases'][phase]+=1
        if sub=='fly' and key not in ledger['board']:ledger['board'][key]=int(s.time)

def metrics_finish(env, ledger):
    generated=len(env.scenario.persons.persons);unfinished=len(set(env.scenario.persons.persons)-set(env.scenario.finished_ids))
    if abs(sum(ledger['individual'].values())-ledger['area'])>1e-6:raise RuntimeError('逐人人时不守恒')
    durations=[float(p.end_time)-float(p.spawn_time) for p in env.scenario.persons.persons.values()
        if getattr(p,'end_time',None) is not None]
    out=dict(ledger,generated=generated,unfinished=unfinished,completion=(generated-unfinished)/generated if generated else None,
        fixed_cutoff_cost=ledger['area']/generated if generated else None,
        full_att=sum(durations)/generated if generated and unfinished==0 and len(durations)==generated else None,
        completed_episode_integral_cost=ledger['area']/generated if generated and unfinished==0 else None,
        cutoff=int(env.scenario.time),whole_population_att_defined=unfinished==0,
        request_identity={str(pid):dict(born=int(p.spawn_time),origin=list(p.origin_position),destination=list(p.destination_position)) for pid,p in env.scenario.persons.persons.items()},
        individual_unit='截止前置积分人时；full_att另以结束时刻减生成时刻，未完成则空；不冒充源奖励积分完全同义',new_training_transitions=0)
    return clean(out)

def compare_people(reference, other):
    if reference.get('request_identity')!=other.get('request_identity'):
        return dict(status='UNPAIRED_REQUEST_IDENTITIES',reason='请求ID/OD不一致，不伪造逐人收益')
    a=reference['individual'];b=other['individual'];ids=set(a)|set(b)
    gains={p:float(a.get(p,0))-float(b.get(p,0)) for p in ids}
    return dict(total_gain=sum(gains.values()),benefited=sum(v>0 for v in gains.values()),
        harmed=sum(v<0 for v in gains.values()),unchanged=sum(v==0 for v in gains.values()),
        worst_harm=max([0.]+[-v for v in gains.values()]),
        gained_person_minutes=sum(max(0,v) for v in gains.values()),
        lost_person_minutes=sum(max(0,-v) for v in gains.values()),per_person_gain=gains)

def gym_class(m):
    import gymnasium as gym
    import numpy as np
    class PhaseEnv(gym.Env):
        """两个决策记录合成一个物理分钟；前阶段奖励为零，后阶段保留原人时奖励。"""
        metadata={}
        def __init__(self, root,task,trace,horizon=500,seed=123,extended=False):
            self.root,self.task,self.trace,self.horizon,self.next_seed=Path(root),task,str(trace),horizon,seed
            self.extended=extended;self.k=3;self.ndelay=3 if extended else 1
            self.env,self.raw=fresh_env(m,root,task,trace,horizon,seed);self.gate=DispatchGate(self.env,m)
            self.pack=self.env.schema.pack;self.phase=0;self.p=0;self.physical_total=0
            self.action_space=gym.spaces.Discrete(3*self.ndelay)
            self.observation_space=gym.spaces.Box(-np.inf,np.inf,(self.pack+8,),np.float32)
            self.ledger=metric_start();self.last_episode=None;self.done=False
        def vector(self):
            pack=self.raw[:self.pack] if self.phase==0 else self.raw[self.pack:2*self.pack]
            return np.concatenate([pack,np.asarray([self.phase]+[float(self.phase and self.p==i) for i in range(3)]+self.gate.metadata(),np.float32)])
        def reset(self,seed=None,options=None):
            super().reset(seed=seed)
            self.env.close();actual=int(self.next_seed if seed is None else seed);self.next_seed=actual+1
            self.env,self.raw=fresh_env(m,self.root,self.task,self.trace,self.horizon,actual)
            self.gate=DispatchGate(self.env,m);self.phase=0;self.p=0;self.done=False;self.ledger=metric_start()
            return self.vector(),{}
        def step(self,action):
            target,delay_idx=divmod(int(action),self.ndelay)
            if self.phase==0:
                metric_tick(self.env,self.ledger)
                active=bool(self.env.scenario.waiting_decisions);self.p=target if active else 0
                self.before_time=float(self.env.scenario.time)
                self.raw=self.env.prepare_step(self.p);self.phase=1
                return self.vector(),0.,False,False,dict(physical_increment=0)
            legal=[i for i,v in enumerate(self.env._legal) if v>.5]
            natural=lq_target(self.env)
            requested=target
            if not self.task.get('space',True):target=natural
            if target not in legal:
                target=natural if natural in legal else legal[0];self.ledger['projection_count']+=1
            delay=DELAYS[delay_idx] if self.extended and self.task.get('temporal',False) else 0
            available=bool([e for e in self.env.scenario.vertiports.evtols_at_vertiport.get('2',[]) if e.state.name=='IDLE' and not e.passenger_ids])
            meaningful=available and any(self.env.scenario.vertiports.vertiport_list[str(v)].person_list for v in m.CANDIDATES[3])
            if self.gate.release or self.gate.remaining or not meaningful:
                delay=0;self.ledger['effectless_air']+=1
            else:self.gate.request=(target,delay)
            self.ledger['decision_count']+=1
            self.ledger['decision_log'].append(dict(time=self.before_time,p=self.p,requested_target=requested,
                applied_target=target,delay=delay,legal=legal,meaningful=meaningful))
            self.raw,reward,done,info=self.env.finish_step(target)
            if abs(float(self.env.scenario.time)-self.before_time-1)>1e-8:raise RuntimeError('物理分钟或奖励重复推进')
            self.phase=0;self.physical_total+=1;self.done=bool(done)
            if done:
                self.last_episode=metrics_finish(self.env,self.ledger)
                self.last_episode['dispatch_events']=list(self.gate.events)
            return self.vector(),float(reward),False,bool(done),dict(info,physical_increment=1)
        def close(self):self.env.close()
    return PhaseEnv

def torch_features(pack):
    import torch
    from torch import nn
    from stable_baselines3.common.torch_layers import BaseFeaturesExtractor
    class PhaseTransformer(BaseFeaturesExtractor):
        """源六帧普通Transformer；附加的阶段及执行器状态对所有组完全相同。"""
        def __init__(self,observation_space,pack=pack):
            super().__init__(observation_space,128);self.pack=pack
            self.input=nn.Linear(28,128);self.position=nn.Parameter(torch.zeros(1,6,128))
            layer=nn.TransformerEncoderLayer(128,4,256,dropout=0.,batch_first=True,activation='relu')
            self.temporal=nn.TransformerEncoder(layer,1,enable_nested_tensor=False)
            self.extra=nn.Linear(observation_space.shape[0]-168,128,bias=False)
        def forward(self,x):return self.temporal(self.input(x[:,:168].reshape(-1,6,28))+self.position)[:,-1]+self.extra(x[:,168:])
    PhaseTransformer.__module__=__name__;PhaseTransformer.__qualname__='PhaseTransformer'
    globals()['PhaseTransformer']=PhaseTransformer
    return PhaseTransformer

def evaluate_predictor(m,root,task,bank,predictor,extended):
    PhaseEnv=gym_class(m);results=[]
    for trace in bank:
        env=PhaseEnv(root,task,trace['path'],600,123,extended)
        try:
            obs,_=env.reset(seed=123);state=None
            while not env.done:
                action,state=predictor(obs,state)
                obs,_,_,_,_=env.step(int(action))
            results.append(dict(trace=trace['name'],trace_sha256=trace['sha256'],metrics=env.last_episode))
        finally:env.close()
    return results

def checkpoint_pickle(path,value):
    p=Path(path);p.parent.mkdir(parents=True,exist_ok=True);tmp=p.with_name(p.name+'.pending')
    with tmp.open('wb') as f:pickle.dump(value,f,protocol=5)
    os.replace(tmp,p)

def preflight(root,device,min_free=8):
    """共享GPU利用率只记录；不因瞬时利用率退出，更不停止其他人的进程。"""
    free=shutil.disk_usage(root).free/1024**3
    if free<min_free:raise RuntimeError(f'磁盘仅剩{free:.1f}GiB，保留已有数据后暂停')
    record=dict(time=time.time(),disk_free_gib=free,cpu=os.cpu_count(),device=device)
    if device=='cuda':
        if not os.environ.get('CUDA_VISIBLE_DEVICES'):raise RuntimeError('请显式指定CUDA_VISIBLE_DEVICES')
        r=subprocess.run(['nvidia-smi','--query-gpu=index,memory.free,utilization.gpu','--format=csv,noheader,nounits'],capture_output=True,text=True)
        record['nvidia_smi']=r.stdout;record['returncode']=r.returncode
        if r.returncode:raise RuntimeError('无法读取GPU；不安装驱动、不强制改为CPU')
    save(Path(root)/'RESOURCE_SNAPSHOT.json',record)

def lock_root(root):
    handle=(Path(root)/'PARENT.lock').open('a+b')
    if os.name=='nt':
        import msvcrt
        handle.write(b'0');handle.flush();handle.seek(0);msvcrt.locking(handle.fileno(),msvcrt.LK_NBLCK,1)
    else:
        import fcntl
        fcntl.flock(handle.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
    return handle

def contract(root, payload, resume):
    old=read(Path(root)/'SUITE_PLAN.json')
    payload=dict(payload,version=VERSION,entrypoint_sha256=digest(__file__),runtime_sha256=RUNTIME_SHA)
    if old and old!=payload:raise RuntimeError('科学合同或代码改变，不能混入旧实验')
    if old and not resume:raise RuntimeError('已有结果，请加--resume')
    if not old:save(Path(root)/'SUITE_PLAN.json',payload)

def pack_outputs(root):
    """同时交付数据和最终恢复件；中间回放缓冲不混入DATAONLY。"""
    root=Path(root);out=PROJECT/'experiment_archives';out.mkdir(exist_ok=True)
    for kind in ('DATAONLY','FINAL_REPLAY_MODELS'):
        target=out/(root.name+'_'+kind+'.tar.gz');tmp=target.with_name(target.name+'.pending')
        with tarfile.open(tmp,'w:gz') as tf:
            tf.add(__file__,arcname=root.name+'/ENTRYPOINT.py',recursive=False)
            for p in sorted(root.rglob('*')):
                if not p.is_file() or p.is_symlink() or any(x in p.parts for x in ('_author_source','cache','vendor','replay')):continue
                if p.name.endswith('.pending') or 'pending_' in p.name:continue
                is_model=p.suffix.lower() in ('.zip','.pkl','.npz','.ckpt')
                if kind=='DATAONLY' and is_model:continue
                if kind=='FINAL_REPLAY_MODELS' and not (is_model or p.name in ('SUITE_PLAN.json','BANK.json','TASK.json','END.json','CONFIG.json','RESUME.json') or p.parent.name=='bank'):continue
                tf.add(p,arcname=root.name+'/'+p.relative_to(root).as_posix(),recursive=False)
        os.replace(tmp,target)
        save(root/(kind+'_PACKAGE.json'),dict(path=str(target),sha256=digest(target),bytes=target.stat().st_size))
        print('[结果包]',target,flush=True)

def launch_job(job,root,deadline):
    folder=Path(root)/'cells'/job['task']['id'];folder.mkdir(parents=True,exist_ok=True)
    save(folder/'JOB.json',job)
    if (folder/'END.json').exists() and read(folder/'END.json').get('status')=='COMPLETE':return 'EXISTING'
    with (folder/'worker.log').open('a',encoding='utf-8') as log:
        child=subprocess.Popen([sys.executable,'-B','-u',str(Path(__file__).resolve()),'--worker',str(folder/'JOB.json')],cwd=PROJECT,stdout=log,stderr=subprocess.STDOUT)
        while child.poll() is None:
            save(Path(root)/'RUNNING.json',dict(task=job['task'],pid=child.pid,live=read(folder/'LIVE.json',{}),time=time.time()))
            if time.time()>deadline or (Path(root)/'STOP_REQUESTED').exists():
                child.terminate()
                try:child.wait(timeout=30)
                except subprocess.TimeoutExpired:child.kill();child.wait()
                save(folder/'INTERRUPTED.json',dict(status='PARTIAL',reason='会话时限或停止请求，只终止自己创建的worker',time=time.time()))
                return 'PARTIAL'
            time.sleep(2)
    if child.returncode:
        save(folder/f'FAILED_{time.time_ns()}.json',dict(exit_code=child.returncode,log=str(folder/'worker.log')))
        return 'FAILED'
    return read(folder/'END.json',{}).get('status','FAILED')

def aggregate(root,tasks):
    rows=[]
    for t in tasks:
        d=Path(root)/'cells'/t['id'];end=read(d/'END.json',{});live=read(d/'LIVE.json',{})
        rows.append(dict(task=t,status=end.get('status','PENDING'),real_steps=end.get('real_steps',live.get('real_steps',0)),
            evaluated=(d/'EVALUATION.json').exists(),seconds=end.get('seconds'),result=end))
    p=dict(total=len(rows),completed=sum(r['status']=='COMPLETE' for r in rows),
        partial=sum(r['status']=='PARTIAL' for r in rows),failed=sum(bool(list((Path(root)/'cells'/r['task']['id']).glob('FAILED_*.json'))) and r['status']!='COMPLETE' for r in rows),
        evaluated=sum(r['evaluated'] for r in rows),measured_training_work=sum(r['real_steps'] for r in rows),rows=rows,time=time.time())
    save(Path(root)/'progress.json',p);return p

def train_ppo(job):
    """两阶段普通PPO；真实环境步数是物理分钟，不把两个决策记录报成两倍样本。"""
    import numpy as np
    import torch
    from stable_baselines3 import PPO
    from stable_baselines3.common.callbacks import BaseCallback
    from stable_baselines3.common.vec_env import SubprocVecEnv, VecNormalize
    root=Path(job['root']);task=job['task'];folder=root/'cells'/task['id'];folder.mkdir(parents=True,exist_ok=True)
    m,native=runtime(root,task);PhaseEnv=gym_class(m);started=time.time()
    target=int(job['steps']);extended=bool(job['extended']);deadline=job['deadline']
    if job['device']=='cuda':torch.cuda.set_per_process_memory_fraction(float(job.get('gpu_fraction',.2)),0)
    def make_one(rank):
        def ctor():return PhaseEnv(root,task,job['trace'],500,task['seed']*10+rank,extended)
        return ctor
    vector=SubprocVecEnv([make_one(i) for i in range(5)],start_method='spawn')
    pointer=read(folder/'RESUME.json',{})
    if pointer:
        if digest(folder/pointer['model'])!=pointer['model_sha'] or digest(folder/pointer['norm'])!=pointer['norm_sha']:
            raise RuntimeError('模型与归一化恢复件不配对')
        norm=VecNormalize.load(str(folder/pointer['norm']),vector)
        model=PPO.load(folder/pointer['model'],env=norm,device=job['device'])
    else:
        if (folder/'MODEL.zip').exists():raise RuntimeError('存在模型但缺恢复指针，保留待查')
        norm=VecNormalize(vector,norm_obs=True,norm_reward=True,gamma=math.sqrt(.99),clip_obs=10.)
        sample=PhaseEnv(root,task,job['trace'],500,123,extended);pack=sample.pack;sample.close()
        features=torch_features(pack)
        model=PPO('MlpPolicy',norm,learning_rate=lambda progress:5e-4*progress,n_steps=4096,batch_size=512,
            n_epochs=10,gamma=math.sqrt(.99),gae_lambda=math.sqrt(.95),clip_range=.25,
            ent_coef=.01,vf_coef=.5,max_grad_norm=.5,seed=task['seed'],device=job['device'],verbose=1,
            policy_kwargs=dict(features_extractor_class=features,net_arch=dict(pi=[256,256],vf=[256,256])))
    initial=model.num_timesteps//2
    def save_pair(name='RESUME'):
        model_path=folder/(name+'.zip');norm_path=folder/(name+'.pkl')
        model.save(model_path.with_name(name+'.pending.zip'));norm.save(str(norm_path.with_name(name+'.pending.pkl')))
        os.replace(model_path.with_name(name+'.pending.zip'),model_path);os.replace(norm_path.with_name(name+'.pending.pkl'),norm_path)
        state=dict(real_steps=model.num_timesteps//2,decision_records=model.num_timesteps,model=model_path.name,norm=norm_path.name,
            model_sha=digest(model_path),norm_sha=digest(norm_path),target_real_steps=target)
        save(folder/(name+'.json'),state)
        return state
    class Recorder(BaseCallback):
        def __init__(self):super().__init__();self.next_save=initial+20480;self.next_eval=next((x for x in job['eval_steps'] if x>initial),target)
        def _on_step(self):
            real=self.model.num_timesteps//2
            if real>=self.next_save and self.model.num_timesteps%10==0:
                save_pair();self.next_save=real+20480
                save(folder/'LIVE.json',dict(phase='train',real_steps=real,decision_records=self.model.num_timesteps,
                    elapsed_seconds=time.time()-started,real_fps=(real-initial)/max(1,time.time()-started),time=time.time()))
            if real>=self.next_eval and self.model.num_timesteps%10==0:
                save_pair(f'CP_{real:09d}');self.next_eval=next((x for x in job['eval_steps'] if x>real),target+1)
            # 只能在完整物理分钟后响应停止，不能把准备阶段误报为半个真实样本。
            return self.model.num_timesteps%10!=0 or (time.time()<deadline and not (root/'STOP_REQUESTED').exists())
    try:
        remaining=max(0,2*target-model.num_timesteps)
        if remaining:model.learn(total_timesteps=remaining,reset_num_timesteps=False,callback=Recorder())
        state=save_pair();status='COMPLETE' if state['real_steps']>=target else 'PARTIAL'
        save(folder/'TRAIN_END.json',dict(status=status,**state,seconds=time.time()-started))
    finally:norm.close()
    # 评估与训练分进程，避免CUDA上下文长期占用与worker相互污染。
    save(folder/'END.json',dict(status=status,real_steps=state['real_steps'],seconds=time.time()-started,
        information='与Dreamer使用同一合法意图解码；不复用旧masked双头基线',
        profile='5x4096决策记录；两阶段每物理分钟；gamma=sqrt(.99)、GAE=sqrt(.95)',
        discount_boundary='折扣在每两记录上为.99；GAE切段、熵及中间价值不等价于旧单分钟PPO，必须新训匹配基线'))

def eval_ppo(job):
    import numpy as np
    from stable_baselines3 import PPO
    root=Path(job['root']);task=job['task'];folder=root/'cells'/task['id']
    m,native=runtime(root,task);sample=gym_class(m)(root,task,job['trace'],500,123,job['extended'])
    torch_features(sample.pack);sample.close()
    end=read(folder/'RESUME.json');model=PPO.load(folder/end['model'],device='cpu')
    class Loader(pickle.Unpickler):
        def find_class(self,mod,name):
            if mod in ('__main__','__mp_main__') and name in globals():return globals()[name]
            return super().find_class(mod,name)
    with (folder/end['norm']).open('rb') as f:norm=Loader(f).load()
    norm.training=False;norm.norm_reward=False
    def predictor(obs,state):
        normalized=norm.normalize_obs(np.asarray(obs)[None])
        a,_=model.predict(normalized,deterministic=not job.get('stochastic_eval',False))
        return int(a[0]),None
    curves=[]
    checkpoints=sorted(folder.glob('CP_*.json'))
    for cp in checkpoints:
        meta=read(cp)
        if meta['real_steps']<.8*job['steps']:continue
        model=PPO.load(folder/meta['model'],device='cpu')
        with (folder/meta['norm']).open('rb') as f:norm=Loader(f).load()
        norm.training=False;norm.norm_reward=False
        rows=evaluate_predictor(m,root,task,job['bank'][:4],predictor,job['extended'])
        curves.append(dict(real_steps=meta['real_steps'],episodes=rows))
    model=PPO.load(folder/end['model'],device='cpu')
    with (folder/end['norm']).open('rb') as f:norm=Loader(f).load()
    norm.training=False;norm.norm_reward=False
    final=evaluate_predictor(m,root,task,job['bank'],predictor,job['extended'])
    save(folder/'EVALUATION.json',dict(task=task,real_steps=end['real_steps'],late_checkpoints=curves,final=final,
        weights_unchanged=True,primary='末20%固定检查点x4301-4304；不足目标时只报PARTIAL不与完整训练混排',
        confirmation='7401-7404条件重排；不是跨分布泛化',new_training_transitions=0))

def suite_parent(args,root_name,tasks,steps,extended,wall_hours,extra=None):
    root=PROJECT/'serial_runs'/root_name;root.mkdir(parents=True,exist_ok=True);lock=lock_root(root)
    start=time.time();deadline=start+wall_hours*3600-120
    m,native=runtime(root,tasks[0]);trace,bank=bank_make(root,native)
    payload=dict(tasks=tasks,steps_per_cell=steps,planned_real_steps=len(tasks)*steps,extended=extended,
        bank=bank,trace_sha256=digest(trace),training_horizon=500,evaluation_horizon=600,extra=extra or {},
        input='原六帧及原描述符；新增仅阶段位置/已选动作/等待命令状态，不增加未来需求')
    contract(root,payload,args.resume);preflight(root,args.device,args.min_free_gib)
    for i,t in enumerate(tasks):
        if time.time()>deadline:break
        save(root/'cells'/t['id']/'TASK.json',t)
        job=dict(root=str(root),task=t,steps=steps,extended=extended,trace=trace,bank=bank,device=args.device,
            deadline=deadline,gpu_fraction=args.gpu_fraction,eval_steps=[steps*j//5 for j in range(1,6)],kind='ppo')
        print(f'[训练 {i+1}/{len(tasks)}]',t['id'],flush=True)
        state=launch_job(job,root,deadline)
        if state in ('COMPLETE','EXISTING'):
            e=dict(job,kind='ppo_eval');print('[评估]',t['id'],flush=True)
            # 评估不复用训练结束标记作为已评估标记。
            folder=root/'cells'/t['id']
            if not (folder/'EVALUATION.json').exists():
                save(folder/'EVAL_JOB.json',e)
                with (folder/'eval.log').open('a',encoding='utf-8') as log:
                    result=subprocess.run([sys.executable,'-B','-u',__file__,'--worker',str(folder/'EVAL_JOB.json')],cwd=PROJECT,stdout=log,stderr=subprocess.STDOUT)
                if result.returncode:save(folder/f'FAILED_EVAL_{time.time_ns()}.json',dict(exit_code=result.returncode))
        aggregate(root,tasks)
    p=aggregate(root,tasks);status='COMPLETE' if p['completed']==len(tasks) and p['evaluated']==len(tasks) else 'PARTIAL'
    save(root/'END.json',dict(status=status,progress=p,session_seconds=time.time()-start))
    save(root/'RUNNING.json',dict(phase=status.lower(),pid=None,time=time.time()));pack_outputs(root);lock.close()

