STAGE_SHA='dc439a685c27afb394c6dcba8f8c4bd9afb6aa7904374e489a379ccad55f8eff'

def discover(source,family):
    source=Path(source).resolve();plan=read(source/'SUITE_PLAN.json')
    if not plan:return [],[dict(source=str(source),reason='缺SUITE_PLAN.json')]
    cases=[];missing=[];step=int(plan['config']['actual_steps'])
    for t in plan['tasks']:
        if t.get('gamma')!=.99:continue
        if t.get('environment')!='E1' or t.get('k')!=3 or t.get('fleet')!=12 or t.get('reward_mode')!='PT_POST':
            raise RuntimeError('模型不在本轮物理/奖励合同内')
        if Path(t['id']).name!=t['id'] or '/' in t['id'] or '\\' in t['id']:raise RuntimeError('任务标识异常')
        pointer=source/'cells'/t['id']/'checkpoints'/f'step_{step:09d}.json'
        if not pointer.exists():missing.append(dict(case=t['id'],reason='固定最终模型尚缺，不按成绩换存档'));continue
        meta=read(pointer);model=pointer.parent/Path(meta['model']).name;norm=pointer.parent/Path(meta['vecnorm']).name
        for p in (model,norm):
            if not p.is_file() or p.is_symlink() or not p.resolve().is_relative_to(source):raise RuntimeError('模型/归一化配对异常')
        cases.append(dict(case=t['id'],task=t,controller='MODEL',family=family,source=str(source),
            model=str(model),norm=str(norm),model_sha=digest(model),norm_sha=digest(norm),training_seed=t['seed']))
    if family=='credit' and len(cases)!=16:raise RuntimeError('76.7M的.99组预期16个，不可静默筛掉坏种子')
    return cases,missing

def diagnostic_runtime(job):
    d=load_module('threeway_old_diagnostic',DIAG_B85,DIAG_SHA)
    case=job['case'];work=Path(job['work']);work.mkdir(parents=True,exist_ok=True)
    if case['family']=='credit':
        original=dict(job,case=case,work=str(work),out=str(work),run_root=job['root'],deadline=float('inf'))
        base,m,model,norm,private=d.runtime(original)
    else:
        stage=load_module('threeway_old_stage',STAGE_B85,STAGE_SHA);m=stage.runtime()
        envroot=work/'environment';d.prepare_author_environment(m,case['task'],envroot)
        base=load_module('stage_frozen_clone',stage.FROZEN_BASE_B85,stage.FROZEN_BASE_SHA)
        model=m.FullPPO.load(case['model'],device='cpu')
        class Loader(pickle.Unpickler):
            def find_class(self,mod,name):
                if mod in ('__main__','__mp_main__') and hasattr(m,name):return getattr(m,name)
                return super().find_class(mod,name)
        with Path(case['norm']).open('rb') as f:norm=Loader(f).load()
        norm.training=False;norm.norm_reward=False;model.policy.set_training_mode(False)
        private=dict(family='pt',task=case['task'],root=str(envroot),out=str(work),run_root=job['root'])
    if digest(case['model'])!=case['model_sha'] or digest(case['norm'])!=case['norm_sha']:raise RuntimeError('输入模型改变')
    for p in model.policy.parameters():p.requires_grad_(False)
    def forbidden(*unused,**kwargs):raise RuntimeError('冻结诊断禁止优化或训练')
    model.learn=model.train=forbidden
    if getattr(model.policy,'optimizer',None):model.policy.optimizer.step=forbidden
    base.check_pause=lambda unused:None
    return d,base,m,model,norm,private

def replay_old(bundle,job,plans=None,forecast=None,end_time=601,collect=False,continuation=None):
    """从episode起点重放前缀，不克隆带generator/绑定方法的半分钟状态。"""
    d,base,m,model,norm,private=bundle;plans={int(k):v for k,v in (plans or {}).items()}
    m.torch.manual_seed(123);m.np.random.seed(123);random.seed(123)
    env,obs=base.env_new(m,private,job['bank']['path'],123);gate=DispatchGate(env,m)
    ledger=metric_start();contexts=[];points={};initial=set();focal=None;cohorts=Counter();initial_time=None
    try:
        with m.torch.no_grad():
            while env.scenario.time<end_time:
                if (Path(job['root'])/'STOP_REQUESTED').exists():raise RuntimeError('用户请求停止诊断')
                before=int(env.scenario.time);active=bool(env.scenario.waiting_decisions)
                focal_id=str(env.scenario.waiting_decisions[0]) if active else None
                existing_ids=list(map(str,env.scenario.persons.persons))
                metric_tick(env,ledger)
                pre=norm.normalize_obs(obs[None]);controller=job['case']['controller']
                if continuation=='READY' and plans and before>min(plans):controller='READY'
                natural_p=int(base.ready(env,m)) if controller=='READY' and active else int(model.policy.sample_passenger(m.torch.as_tensor(pre,device='cpu'),True)[0][0]) if active else 0
                plan=plans.get(before,{})
                p=int(plan.get('p',natural_p));pending_raw=env.prepare_step(p)
                legal=[i for i,v in enumerate(env._legal) if v>.5]
                if env.joint and controller!='READY':
                    pending=norm.normalize_obs(pending_raw[None]);pending[:,:env.schema.pack]=pre[:,:env.schema.pack]
                    natural_air=int(model.policy.sample_return(m.torch.as_tensor(pending,device='cpu'),m.torch.as_tensor([p]),True)[0])
                else:natural_air=-1
                candidates=[i for i,v in enumerate(m.CANDIDATES[3]) if env.scenario.vertiports.vertiport_list[str(v)].person_list]
                available=len([e for e in env.scenario.vertiports.evtols_at_vertiport.get('2',[]) if e.state.name=='IDLE' and not e.passenger_ids])
                meaningful=bool(env.joint and available and candidates)
                state_hash=d.object_sha(d.state_view(env))
                if collect:
                    contexts.append(dict(time=before,post_time=int(env.scenario.time),active=active,p=p,air=natural_air,
                        legal=legal,meaningful=meaningful,available=available,unfinished=m.attr_unfinished(env.scenario),
                        focal_id=focal_id,existing_ids=existing_ids,
                        state_sha=state_hash,history=d.public_history(env),
                        generation_ended=before>=env.scenario.passenger_generation_end_time))
                if forecast is not None and before==int(forecast[0]):
                    # 只在达到真实当前状态后替换未揭示后缀；选择器从不接触原未来CSV。
                    env.scenario.persons.file_data=__import__('copy').deepcopy(forecast[1])
                air=int(plan.get('target',natural_air));delay=int(plan.get('delay',0))
                if air>=0 and air not in legal:
                    ledger['projection_count']+=1;air=natural_air if natural_air in legal else legal[0]
                if meaningful and (plan or (gate.release or gate.remaining)):
                    if not gate.release and not gate.remaining:gate.request=(air,delay)
                if not meaningful:ledger['effectless_air']+=1
                ledger['decision_count']+=1
                ledger['decision_log'].append(dict(time=before,p=p,air=natural_air,applied_air=air,delay=delay,
                    active=active,meaningful=meaningful,state_sha=state_hash))
                obs,_,done,_=env.finish_step(air)
                points[int(env.scenario.time)]=ledger['area']
                if done:break
        result=metrics_finish(env,ledger);result['contexts']=contexts;result['area_curve']=points;result['gate_events']=gate.events
        result['source_model']=job['case']['case'];result['trace']=job['bank']['name']
        result['replay_protocol']='从起点重放；请求CSV相同，初始随机状态相同；不声称动作分叉后随机消耗仍逐事件完全一致'
        return result
    finally:env.close()

def sample_contexts(contexts,count):
    """按时期及有无新乘客分层；缺少机会保留缺样，不补造。"""
    pools={}
    for c in contexts:
        if not c['meaningful'] or c['unfinished']<12:continue
        key=(min(3,c['time']//100),bool(c['active']))
        pools.setdefault(key,[]).append(c)
    result=[];rng=random.Random(20261104)
    for key,rows in sorted(pools.items()):
        take=min(len(rows),max(1,count//max(1,len(pools))))
        result.extend(rng.sample(rows,take))
    # 允许不足计划数，禁止因为回放成绩而补抽不同状态。
    return sorted(result,key=lambda x:x['time'])[:count]

def suffix_gain(reference,other,start,horizon=None):
    boundary=min(reference['cutoff'],other['cutoff'],start+horizon if horizon else 601)
    def cost(r,t):
        keys=sorted(int(k) for k in r['area_curve'] if int(k)<=t)
        return r['area_curve'].get(str(max(keys)),r['area_curve'].get(max(keys),0)) if keys else 0.
    return (cost(reference,boundary)-cost(reference,start))-(cost(other,boundary)-cost(other,start))

def run_diagnostic_job(job):
    folder=Path(job['work']);folder.mkdir(parents=True,exist_ok=True);started=time.time()
    bundle=diagnostic_runtime(job);d,base,m,model,norm,private=bundle
    before=m.policy_sha(model.policy);reference=replay_old(bundle,job,collect=True)
    check=replay_old(bundle,job)
    if reference['area']!=check['area'] or reference['individual']!=check['individual']:
        raise RuntimeError('从起点参考重放不复现，不发布归因')
    save(folder/'BASELINE.json',reference)
    contexts=sample_contexts(reference['contexts'],job['states']);missing=[];tables=[];pairs=[];calls=2
    if job['case']['task']['control']!='J3':
        save(folder/'END.json',dict(status='COMPLETE',reference_only=True,seconds=time.time()-started,
            new_training_transitions=0,coverage='单侧没有学习飞机权限，不强行套联合空间时间干预'));return
    for context in contexts:
        at=context['time'];state_dir=folder/'states'/str(at)
        plans=[dict(target=context['air'],delay=0)]
        targets=context['legal'] if job['case']['controller']!='READY' else [-1]+context['legal']
        for target in targets:
            for delay in DELAYS:
                p=dict(target=target,delay=delay)
                if p not in plans:plans.append(p)
        cached=read(state_dir/'END.json');outputs=cached['outputs'] if cached else []
        if not cached:
            for plan in plans:
                current=replay_old(bundle,job,{at:plan});calls+=1
                gain=compare_people(reference,current)
                if 'total_gain' not in gain:raise RuntimeError('固定trace的分支请求身份不一致')
                cohorts=Counter();existing=set(context['existing_ids'])
                for pid,value in gain['per_person_gain'].items():
                    label='focal' if pid==context['focal_id'] else 'existing' if pid in existing else 'future'
                    cohorts[label]+=value
                outputs.append(dict(plan=plan,cost=current['area'],gain=gain,completion=current['completion'],
                    cohort_gain=dict(cohorts),
                    gain_60=suffix_gain(reference,current,at,60),gain_120=suffix_gain(reference,current,at,120),
                    gain_before300=suffix_gain(reference,current,at,300-at) if at<300 else None,
                    phase_gain={k:reference['phases'].get(k,0)-current['phases'].get(k,0) for k in ('ground','wait','flight')},
                    gate_events=current['gate_events'],unfinished=current['unfinished']))
        # 原命令零等待必须与原轨迹一致。READY保持-1即保留原LQ规则，而非硬指派某个机场。
        if abs(outputs[0]['cost']-reference['area'])>1e-7:raise RuntimeError('零干预改变了原调度，不能当纯时空归因')
        by={(r['plan']['target'],r['plan']['delay']):r for r in outputs}
        for target in context['legal']:
            for delay in (1,3):
                keys=[(context['air'],0),(target,0),(context['air'],delay),(target,delay)]
                if all(k in by for k in keys):
                    c=[by[k]['cost'] for k in keys]
                    pairs.append(dict(time=at,target=target,delay=delay,interaction=c[3]-c[1]-c[2]+c[0],
                        costs=c,meaning='固定候选四臂的人时交互，非独立样本、非总gap份额'))
        tables.append(dict(time=at,state_sha=context['state_sha'],active=context['active'],
            min_spatial_cost=min(r['cost'] for r in outputs if r['plan']['delay']==0),
            min_time_cost=min(r['cost'] for r in outputs if r['plan']['target']==context['air']),
            min_both_cost=min(r['cost'] for r in outputs),reference_cost=reference['area'],
            candidates=len(outputs),ranking_60=[r['plan'] for r in sorted(outputs,key=lambda x:-x['gain_60'])],
            ranking_full=[r['plan'] for r in sorted(outputs,key=lambda x:-x['gain']['total_gain'])]))
        save(state_dir/'END.json',dict(context=context,outputs=outputs,reference_matched=True,
            privileged_scoring=True,policy_future_input=False,new_training_transitions=0))
    save(folder/'SPACE_TIME.json',dict(states=tables,factorial=pairs,missing=missing,
        limitation='事后候选受限上限；更大的候选集合天然有更多挑选机会，最小值不能直接解释为主要原因',
        ready_boundary='READY的-1是动态LQ规则；等待时保留规则，不等于固定同一批飞机的每个实际目标'))
    # 只在正常运行时段做合法在线对照；不把清场单独升级为主线。
    online=[]
    if job.get('online',True):
        for mode in ('space','time','both'):
            picked={};records=[]
            for nominal in (80,180):
                prefix=replay_old(bundle,job,picked,collect=True);calls+=1
                current=next((c for c in prefix['contexts'] if nominal<=c['time']<nominal+20 and c['meaningful']),None)
                if current is None:records.append(dict(gate=nominal,status='NO_REAL_OPPORTUNITY'));continue
                at=current['time'];history=current['history']
                worlds=[d.forecast_world(history,84010+i,120) for i in range(8)]
                if any(w is None for w in worlds):records.append(dict(gate=nominal,status='INSUFFICIENT_HISTORY'));continue
                choices=[dict(target=current['air'],delay=0)]
                targets=current['legal'] if mode!='time' else [current['air']]
                for target in targets:
                    for delay in (DELAYS if mode!='space' else (0,)):
                        choice=dict(target=target,delay=delay)
                        if choice not in choices:choices.append(choice)
                costs=[]
                for choice in choices:
                    row=[]
                    for world in worlds:
                        trial=replay_old(bundle,job,dict(picked,**{str(at):choice}),forecast=(at,world),end_time=min(601,at+120))
                        row.append(trial['area']);calls+=1
                    costs.append(row)
                pick=lambda sl:min(range(len(choices)),key=lambda i:(sum(costs[i][sl])/len(costs[i][sl]),i!=0,i))
                selected=pick(slice(None));picked[at]=choices[selected]
                records.append(dict(time=at,choice=choices[selected],half_draws_agree=pick(slice(0,4))==pick(slice(4,8)),
                    history_sha=d.object_sha(history),world_hashes=[d.object_sha(w) for w in worlds],
                    costs=costs,no_actual_future_used=True))
            actual=replay_old(bundle,job,picked);calls+=1
            online.append(dict(mode=mode,decisions=records,metrics=actual,gain=compare_people(reference,actual)))
        save(folder/'LEGAL_ONLINE.json',dict(results=online,new_training_transitions=0,
            rule='只用历史采样世界挑动作，再用真实请求回放核对；每场最多两次修正，不称完整MPC'))
    if before!=m.policy_sha(model.policy):raise RuntimeError('诊断改动了模型权重')
    save(folder/'END.json',dict(status='COMPLETE',seconds=time.time()-started,branch_calls=calls,
        sampled_states=len(contexts),weights_unchanged=True,new_training_transitions=0))

def collect_new(root,targets):
    """第三入口汇集另两组的运行指标；缺记录明确留空，不替代冻结模型分支诊断。"""
    result={}
    for name in targets:
        folder=PROJECT/'serial_runs'/name
        rows=[]
        for p in sorted((folder/'cells').glob('*/EVALUATION.json')):
            data=read(p);task=data['task'];fit=read(p.parent/'WORLD_MODEL_FIT.json')
            rows.append(dict(task=task,evaluation=data,model_fit=fit,training=read(p.parent/'TRAIN_END.json'),
                update_audit=read(p.parent/'UPDATE_AUDIT.json'),configuration=read(p.parent/'CONFIG.json')))
        paired=[];base_arm='PPO_TF' if 'hot_transfer' in name else 'S0_T0'
        base={(r['task']['seed'],e['trace']):e for r in rows if r['task']['arm']==base_arm for e in r['evaluation'].get('final',[])}
        for row in rows:
            for episode in row['evaluation'].get('final',[]):
                ref=base.get((row['task']['seed'],episode['trace']))
                if ref and ref['trace_sha256']==episode['trace_sha256']:
                    paired.append(dict(seed=row['task']['seed'],arm=row['task']['arm'],trace=episode['trace'],
                        gain=compare_people(ref['metrics'],episode['metrics']),
                        caution='只有相同训练步数/完整状态才可归入等预算主表；不同步数这里只作描述'))
        result[name]=dict(end=read(folder/'END.json'),progress=read(folder/'progress.json'),models=rows,paired_individual=paired)
    save(Path(root)/'NEW_TRAINING_DIAGNOSTICS.json',result)
    return result

def main():
    ap=argparse.ArgumentParser(description='综合冻结诊断：覆盖、空间时间、合法预测、逐人损失及训练后适配核验')
    ap.add_argument('--resume',action='store_true');ap.add_argument('--worker');ap.add_argument('--plan',action='store_true')
    ap.add_argument('--workers',type=int,default=2);ap.add_argument('--states',type=int,default=12)
    ap.add_argument('--source',type=Path,default=PROJECT/'serial_runs/uam_credit_horizon_32run_18h_v1')
    ap.add_argument('--stage-source',type=Path,default=PROJECT/'serial_runs/uam_stage_stin_24run_60m_v1')
    ap.add_argument('--follow-new',action='store_true');ap.add_argument('--follow-hours',type=float,default=54.)
    ap.add_argument('--no-online',action='store_true');args=ap.parse_args()
    if args.plan:
        print(json.dumps(dict(states_per_episode=args.states,workers=args.workers,new_training_transitions=0,
            diagnostic_families=['完整覆盖','纯空间/等待/组合','短长窗口排序','合法预测整场','个体收益损失','新方法预测拟合与服务结果联查'],
            no_runtime_promise='不再强行塞满两小时；按真实可用状态计算，缺样不补造'),ensure_ascii=False,indent=2));return
    if args.worker:
        job=read(args.worker)
        try:run_diagnostic_job(job)
        except Exception:
            save(Path(job['work'])/f'FAILED_{time.time_ns()}.json',dict(traceback=traceback.format_exc()));raise
        return
    if not 1<=args.workers<=2:raise RuntimeError('共享服务器默认至多两个CPU诊断worker，不扩大占用')
    root=PROJECT/'workspace/artifacts/uam_threeway_diagnostics_20261104_v1';root.mkdir(parents=True,exist_ok=True);lock=lock_root(root)
    cases,missing=discover(args.source,'credit');stage,miss=discover(args.stage_source,'stage');missing+=miss
    # 全部普通源模型做覆盖；深分支固定选择.99的联合模型及60M的原普通JOINT，不按性能筛选。
    deep=[c for c in cases if c['task']['control']=='J3']
    deep.extend(c for c in stage if c['task']['control']=='J3' and c['task']['arm']=='JOINT')
    ready=dict(next(c for c in cases if c['task']['control']=='J3'));ready.update(case='READY_J3',controller='READY',training_seed=None)
    all_cases=[ready]+cases+stage
    m,native=runtime(root,task_record('DIAGNOSTIC',0));_,bank=bank_make(root,native);bank=[b for b in bank if b['name'] in ('order_4303','order_4304')]
    jobs=[]
    for case in all_cases:
        for b in bank:
            work=root/'cells'/case['case']/b['name']
            jobs.append(dict(root=str(root),work=str(work),case=case,bank=b,states=args.states if case in deep or case['controller']=='READY' else 0,
                online=not args.no_online and (case in deep or case['controller']=='READY')))
    contract(root,dict(cases=all_cases,missing=missing,states=args.states,bank=bank,online=not args.no_online,
        statistics='训练seed是独立单位；同模型多状态和多个候选不是额外seed',
        new_training_transitions=0,method='起点前缀重放，不克隆generator；没有真实未来输入选择器'),args.resume)
    save(root/'MISSING_INPUTS.json',missing);preflight(root,'cpu')
    from concurrent.futures import ThreadPoolExecutor,as_completed
    def launch(job):
        folder=Path(job['work']);folder.mkdir(parents=True,exist_ok=True)
        if (folder/'END.json').exists():return read(folder/'END.json')
        save(folder/'JOB.json',job)
        with (folder/'worker.log').open('a',encoding='utf-8') as log:
            result=subprocess.run([sys.executable,'-B','-u',__file__,'--worker',str(folder/'JOB.json')],cwd=PROJECT,stdout=log,stderr=subprocess.STDOUT)
        return dict(case=job['case']['case'],trace=job['bank']['name'],exit_code=result.returncode,**read(folder/'END.json',dict(status='FAILED')))
    results=[];start=time.time()
    with ThreadPoolExecutor(max_workers=args.workers) as pool:
        pending={pool.submit(launch,j):j for j in jobs}
        for future in as_completed(pending):
            try:result=future.result()
            except Exception:result=dict(status='FAILED',traceback=traceback.format_exc())
            results.append(result);print('[诊断]',len(results),'/',len(jobs),result.get('status'),flush=True)
            save(root/'progress.json',dict(phase='frozen_replay',completed=len(results),total=len(jobs),results=results,new_training_transitions=0))
    targets=['uam_hot_transfer_16run_40h_v1','uam_space_time_16run_48m_v1'];new=collect_new(root,targets)
    save(root/'FROZEN_END.json',dict(status='COMPLETE' if all(r.get('status')=='COMPLETE' for r in results) else 'PARTIAL',
        results=results,wall_seconds=time.time()-start,new_training_transitions=0))
    while args.follow_new and time.time()-start<args.follow_hours*3600:
        new=collect_new(root,targets)
        if all(new[name]['end'] is not None for name in targets):break
        if (root/'STOP_REQUESTED').exists():break
        time.sleep(30)
    save(root/'END.json',dict(status=read(root/'FROZEN_END.json')['status'],wall_seconds=time.time()-start,
        source_coverage=missing,new_training_transitions=0,new_training_finished={k:v['end'] is not None for k,v in new.items()},
        warning='诊断不是适配性成功认证；热点预测精度、个体损失和实际服务增益必须合看'))
    pack_outputs(root);lock.close()

if __name__=='__main__':main()
